const lifecycle = new Set(['in_progress', 'requires_action', 'completed', 'failed', 'cancelled', 'incomplete']);

export function extractInteraction(envelope) {
  if (!envelope || typeof envelope !== 'object') return { ok: false, reason: 'invalid_shape' };
  if (!Number.isInteger(envelope.httpStatus) || envelope.httpStatus < 100 || envelope.httpStatus > 599) return { ok: false, reason: 'invalid_http_status' };
  if (envelope.applicationPolicy === 'refused') return { ok: false, reason: 'application_refusal' };
  if (envelope.httpStatus < 200 || envelope.httpStatus > 299) return { ok: false, reason: 'http_error' };
  const body = envelope.body;
  if (!body || typeof body !== 'object') return { ok: false, reason: 'invalid_shape' };
  if (!lifecycle.has(body.status)) return { ok: false, reason: 'invalid_status' };
  if (body.status === 'in_progress') return { ok: false, reason: 'pending' };
  if (body.status === 'requires_action') return { ok: false, reason: 'requires_action' };
  if (body.status !== 'completed') return { ok: false, reason: 'terminal_nonanswer' };
  if (!Array.isArray(body.steps)) return { ok: false, reason: 'invalid_shape' };
  let firstText;
  for (const step of body.steps) {
    if (!step || typeof step !== 'object') return { ok: false, reason: 'invalid_shape' };
    if (step.type !== 'model_output') continue;
    if (!Array.isArray(step.content)) return { ok: false, reason: 'invalid_shape' };
    for (const part of step.content) {
      if (!part || typeof part !== 'object') return { ok: false, reason: 'invalid_shape' };
      if (part.type === 'text' && typeof part.text === 'string' && firstText === undefined) firstText = part.text;
    }
  }
  return firstText === undefined ? { ok: false, reason: 'no_text' } : { ok: true, text: firstText };
}
