import { isDeepStrictEqual } from 'node:util';
import { fixtures } from './fixtures.mjs';
import { extractInteraction } from './learner.mjs';

let passed = 0;
let failed = 0;
for (const fixture of fixtures) {
  let actual;
  try {
    actual = extractInteraction(fixture.envelope);
  } catch (error) {
    actual = { threw: true, name: error?.name ?? 'UnknownError' };
  }
  if (isDeepStrictEqual(actual, fixture.expected)) {
    console.log(`PASS ${fixture.name}`);
    passed++;
  } else {
    console.log(`FAIL ${fixture.name}: expected ${JSON.stringify(fixture.expected)}, got ${JSON.stringify(actual)}`);
    failed++;
  }
}
console.log(`${passed} passed, ${failed} failed`);
process.exitCode = failed === 0 ? 0 : 1;
