const lifecycle = new Set(['in_progress', 'requires_action', 'completed', 'failed', 'cancelled', 'incomplete']);

export function extractInteraction(envelope) {
  if (!envelope || typeof envelope !== 'object') return { ok: false, reason: 'invalid_shape' };
  if (!Number.isInteger(envelope.httpStatus) || envelope.httpStatus < 100 || envelope.httpStatus > 599) return { ok: false, reason: 'invalid_http_status' };
  if (envelope.applicationPolicy === 'refused') return { ok: false, reason: 'application_refusal' };
  if (envelope.httpStatus < 200 || envelope.httpStatus > 299) return { ok: false, reason: 'http_error' };
  const body = envelope.body;
  if (!body || typeof body !== 'object') return { ok: false, reason: 'invalid_shape' };
  if (!lifecycle.has(body.status)) return { ok: false, reason: 'invalid_status' };
  if (body.status === 'in_progress') return { ok: false, reason: 'pending' };
  if (body.status === 'requires_action') return { ok: false, reason: 'requires_action' };
  if (body.status !== 'completed') return { ok: false, reason: 'terminal_nonanswer' };
  if (!Array.isArray(body.steps)) return { ok: false, reason: 'invalid_shape' };
  const texts = [];
  for (const step of body.steps) {
    if (!step || typeof step !== 'object') return { ok: false, reason: 'invalid_shape' };
    if (step.type !== 'model_output') continue;
    if (!Array.isArray(step.content)) return { ok: false, reason: 'invalid_shape' };
    for (const part of step.content) {
      if (!part || typeof part !== 'object') return { ok: false, reason: 'invalid_shape' };
      if (part.type === 'text' && typeof part.text === 'string') texts.push(part.text);
    }
  }
  return texts.length === 0 ? { ok: false, reason: 'no_text' } : { ok: true, text: texts.join('\n') };
}

const apiKey = process.env.GEMINI_API_KEY;
const model = process.env.PROJECT42_GEMINI_MODEL;
if (!apiKey || !model) {
  console.error(JSON.stringify({ event: 'configuration_failure', missingCredentialOrModel: true }));
  process.exit(2);
}

const lifecycle = new Set(['in_progress', 'requires_action', 'completed', 'failed', 'cancelled', 'incomplete']);
const started = Date.now();
let response;
try {
  response = await fetch('https://generativelanguage.googleapis.com/v1beta/interactions', {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-goog-api-key': apiKey
    },
    body: JSON.stringify({
      model,
      input: 'Return one short sentence explaining why input validation matters.',
      store: false
    }),
    signal: AbortSignal.timeout(30000)
  });
} catch (error) {
  console.error(JSON.stringify({ event: 'transport_failure', errorName: error?.name ?? 'UnknownError', elapsedMs: Date.now() - started }));
  process.exit(3);
}

const httpStatus = response.status;
let body;
try {
  body = await response.json();
} catch {
  console.error(JSON.stringify({ event: 'invalid_json', httpStatus, elapsedMs: Date.now() - started }));
  process.exit(4);
}

if (!response.ok) {
  console.error(JSON.stringify({ event: 'http_failure', httpStatus, elapsedMs: Date.now() - started }));
  process.exit(5);
}
if (!body || typeof body !== 'object' || !lifecycle.has(body.status)) {
  console.error(JSON.stringify({ event: 'invalid_lifecycle_or_shape', httpStatus, elapsedMs: Date.now() - started }));
  process.exit(6);
}
if (body.status === 'in_progress') {
  console.error(JSON.stringify({ event: 'pending', httpStatus, lifecycleStatus: body.status, elapsedMs: Date.now() - started }));
  process.exit(7);
}
if (body.status === 'requires_action') {
  console.error(JSON.stringify({ event: 'requires_action', httpStatus, lifecycleStatus: body.status, elapsedMs: Date.now() - started }));
  process.exit(8);
}
if (body.status !== 'completed') {
  console.error(JSON.stringify({ event: 'terminal_nonanswer', httpStatus, lifecycleStatus: body.status, elapsedMs: Date.now() - started }));
  process.exit(9);
}
if (!Array.isArray(body.steps)) {
  console.error(JSON.stringify({ event: 'invalid_steps_shape', httpStatus, elapsedMs: Date.now() - started }));
  process.exit(10);
}

const texts = [];
for (const step of body.steps) {
  if (!step || typeof step !== 'object') {
    console.error(JSON.stringify({ event: 'invalid_step_shape', httpStatus, elapsedMs: Date.now() - started }));
    process.exit(11);
  }
  if (step.type !== 'model_output') continue;
  if (!Array.isArray(step.content)) {
    console.error(JSON.stringify({ event: 'invalid_content_shape', httpStatus, elapsedMs: Date.now() - started }));
    process.exit(12);
  }
  for (const part of step.content) {
    if (!part || typeof part !== 'object') {
      console.error(JSON.stringify({ event: 'invalid_part_shape', httpStatus, elapsedMs: Date.now() - started }));
      process.exit(13);
    }
    if (part.type === 'text' && typeof part.text === 'string') texts.push(part.text);
  }
}
if (texts.length === 0) {
  console.error(JSON.stringify({ event: 'completed_without_text', httpStatus, elapsedMs: Date.now() - started }));
  process.exit(14);
}
console.error(JSON.stringify({ event: 'completed', httpStatus, elapsedMs: Date.now() - started }));
console.log(texts.join('\n'));
